CREATE OR REPLACE FUNCTION battle_spectator_media_private.close_epoch_for_processing_hold(p_match uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e battle_spectator_media_private.epochs%rowtype;
begin
  select * into e from battle_spectator_media_private.epochs where match_id=p_match for update;
  if found and e.media_open then
    insert into battle_spectator_media_private.revocations(match_id,epoch,reason)
      values(p_match,e.epoch,'processing_hold') on conflict do nothing;
    update battle_spectator_media_private.epochs set media_open=false,updated_at=clock_timestamp()
      where match_id=p_match;
  end if;
end $function$

CREATE OR REPLACE FUNCTION battle_spectator_media_private.sync_epoch(p_match uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.battle_matches%rowtype;c battle_spectator_media_private.config%rowtype;
  g uuid;o boolean;e battle_spectator_media_private.epochs%rowtype;
begin
  -- Consistent lock order with Hold and D1: match, then epoch. Never lock peer profiles here.
  select * into m from public.battle_matches where id=p_match for update;
  if not found then raise exception 'spectator_media_unavailable' using errcode='42501';end if;
  select * into c from battle_spectator_media_private.config where singleton;
  if exists(select 1 from public.profiles p where p.id in(m.host_id,m.guest_id) and p.data_processing_restricted_at is not null) then
    perform battle_spectator_media_private.close_epoch_for_processing_hold(p_match);
    select * into e from battle_spectator_media_private.epochs where match_id=p_match;
    return jsonb_build_object('media_open',false,'epoch',e.epoch,
      'max_viewers_per_match',c.max_viewers_per_match,'consent_version',c.consent_version);
  end if;
  select generation into g from battle_spectator_private.links where match_id=p_match and enabled;
  o:=c.media_enabled and m.guest_id is not null and m.status in('waiting','ready','live')
    and m.moderation_state is distinct from 'paused' and m.paused_at is null
    and exists(select 1 from battle_spectator_media_private.consents x where x.match_id=p_match and x.user_id=m.host_id and x.granted and x.consent_version=c.consent_version)
    and exists(select 1 from battle_spectator_media_private.consents x where x.match_id=p_match and x.user_id=m.guest_id and x.granted and x.consent_version=c.consent_version)
    and (m.visibility='public' or g is not null);
  select * into e from battle_spectator_media_private.epochs where match_id=p_match for update;
  if not found then
    insert into battle_spectator_media_private.epochs(match_id,generation,media_open) values(p_match,g,o) returning * into e;
  elsif exists(select 1 from battle_spectator_media_private.revocations r where r.match_id=p_match and r.epoch=e.epoch and r.reason='processing_hold') then
    -- Defensive reuse boundary only: no unhold endpoint is introduced. Normal eligibility above
    -- must already be restored by an existing trusted path before a new open epoch is possible.
    if o then
      update battle_spectator_media_private.epochs set epoch=gen_random_uuid(),generation=g,media_open=true,updated_at=clock_timestamp()
        where match_id=p_match returning * into e;
    end if;
  elsif e.generation is distinct from g or(e.media_open and not o) then
    perform battle_spectator_media_private.close_epoch(p_match,case when e.generation is distinct from g then 'generation_changed' else 'media_closed' end);
    update battle_spectator_media_private.epochs set generation=g,media_open=o where match_id=p_match returning * into e;
  elsif e.media_open is distinct from o then
    update battle_spectator_media_private.epochs set media_open=o where match_id=p_match returning * into e;
  end if;
  return jsonb_build_object('media_open',e.media_open,'epoch',e.epoch,
    'max_viewers_per_match',c.max_viewers_per_match,'consent_version',c.consent_version);
end $function$

CREATE OR REPLACE FUNCTION battle_spectator_private.actor_session(p_require_eligible boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_sid uuid;
begin
  if v_uid is null or coalesce(auth.jwt()->>'role','') <> 'authenticated'
     or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then
    raise exception 'spectator_not_authenticated' using errcode='42501';
  end if;
  begin v_sid := nullif(auth.jwt()->>'session_id','')::uuid;
  exception when invalid_text_representation then
    raise exception 'spectator_session_unavailable' using errcode='42501'; end;
  if not exists (select 1 from auth.sessions s where s.id=v_sid and s.user_id=v_uid
    and (s.not_after is null or s.not_after>clock_timestamp())) then
    raise exception 'spectator_session_unavailable' using errcode='42501';
  end if;
  if p_require_eligible and not battle_spectator_private.eligible(v_uid) then
    raise exception 'spectator_battle_access_required' using errcode='42501';
  end if;
  return v_sid;
end $function$

CREATE OR REPLACE FUNCTION public.clear_my_battle_signals(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.battle_matches
    where id = p_match_id and auth.uid() in (host_id, guest_id)
  ) then
    raise exception 'not_allowed';
  end if;
  delete from public.battle_signals
  where match_id = p_match_id
    and (sender_id = auth.uid() or created_at < now() - interval '1 day');
end;
$function$

CREATE OR REPLACE FUNCTION public.create_battle_match_v2(p_tcg text, p_visibility text DEFAULT 'public'::text, p_title text DEFAULT NULL::text, p_language text DEFAULT 'de'::text, p_mode text DEFAULT 'casual'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_profile public.profiles; v_code text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_tcg not in ('pokemon','one_piece') then raise exception 'Ungültiges TCG'; end if;
  if p_visibility not in ('public','private') then raise exception 'Ungültige Sichtbarkeit'; end if;
  if p_mode not in ('casual','ranked') then raise exception 'Ungültiger Modus'; end if;
  if p_mode='ranked' and p_visibility<>'public' then raise exception 'Ranked Matches sind in der Beta nur öffentlich'; end if;

  select * into v_profile from public.profiles where id=auth.uid() for share;
  if v_profile.id is null then raise exception 'Profil nicht gefunden'; end if;
  if coalesce(v_profile.account_status,'beta') not in ('beta','active') then raise exception 'Account ist nicht aktiv'; end if;
  if coalesce(v_profile.safety_restricted,false) then raise exception 'BATTLE ist für diesen Account eingeschränkt'; end if;
  if v_profile.data_processing_restricted_at is not null then
    raise exception 'account_data_processing_restricted' using errcode='42501';
  end if;

  if exists(select 1 from public.battle_matches where (host_id=auth.uid() or guest_id=auth.uid()) and status in ('waiting','ready','live','dispute')) then
    raise exception 'Du hast bereits ein aktives Match';
  end if;

  if p_visibility='private' then v_code:=upper(substr(md5(gen_random_uuid()::text),1,6)); end if;
  insert into public.battle_matches(host_id,tcg,mode,visibility,invite_code,title,language,host_display_name,host_founder_number)
  values(auth.uid(),p_tcg,p_mode,p_visibility,v_code,nullif(trim(p_title),''),coalesce(nullif(p_language,''),'de'),coalesce(v_profile.display_name,v_profile.username,'DUELVANTA Player'),v_profile.founder_number)
  returning id into v_id;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.get_battle_disputes_for_moderation()
 RETURNS TABLE(id uuid, tcg text, mode text, status text, host_display_name text, guest_display_name text, host_result text, guest_result text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin perform public.require_duelvanta_privileged_session();
 if auth.uid() is null then raise exception 'not_authenticated'; end if;
 if not public.has_staff_permission('battle_moderate',auth.uid()) then raise exception 'battle_moderate permission required'; end if;
 return query select m.id,m.tcg,m.mode,m.status,m.host_display_name,m.guest_display_name,m.host_result,m.guest_result,m.created_at
 from public.battle_matches m where m.status='dispute' order by m.created_at asc limit 100;
end $function$

CREATE OR REPLACE FUNCTION public.get_battle_spectator_media_publisher_admission(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.battle_matches%rowtype; s jsonb; role_name text;
begin
  perform battle_spectator_private.actor_session();
  select * into m from public.battle_matches where id=p_match_id;
  if not found or (auth.uid() is distinct from m.host_id and auth.uid() is distinct from m.guest_id) then
    raise exception 'spectator_media_player_only' using errcode='42501';
  end if;
  s:=battle_spectator_media_private.sync_epoch(p_match_id);
  if not coalesce((s->>'media_open')::boolean,false) then
    raise exception 'spectator_media_closed' using errcode='42501';
  end if;
  role_name:=case when auth.uid()=m.host_id then 'host' else 'guest' end;
  return jsonb_build_object('match_id',p_match_id,'epoch',s->>'epoch','publisher_role',role_name,'admission_expires_at',clock_timestamp()+interval '30 seconds');
end
$function$

CREATE OR REPLACE FUNCTION public.get_battle_spectator_status(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_match public.battle_matches%rowtype;
begin
  perform battle_spectator_private.actor_session();
  select * into v_match from public.battle_matches where id=p_match_id;
  if not found or (auth.uid() is distinct from v_match.host_id and auth.uid() is distinct from v_match.guest_id
      and auth.uid() is distinct from v_match.moderator_id) then
    raise exception 'spectator_status_for_participants_only' using errcode='42501'; end if;
  return jsonb_build_object('spectator_count',battle_spectator_private.viewer_count(p_match_id),
    'link_enabled',coalesce((select enabled from battle_spectator_private.links where match_id=p_match_id),false));
end $function$

CREATE OR REPLACE FUNCTION public.get_owner_battle_safety_causes(p_target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform public.require_duelvanta_privileged_session();
 if not public.is_duelvanta_owner(auth.uid()) then raise exception 'owner_access_required' using errcode='42501'; end if;
 return jsonb_build_object('target_id',p_target_id,'data_rights_blocked',dv_market_private.b1_data_rights_blocked(p_target_id),
 'causes',(select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('active',r.cause_id is null,'release',to_jsonb(r)) order by c.created_at,c.id),'[]'::jsonb)
 from dv_market_private.battle_safety_causes c left join dv_market_private.battle_safety_releases r on r.cause_id=c.id where c.target_id=p_target_id));
end $function$

CREATE OR REPLACE FUNCTION public.guard_battle_signal_processing_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare restricted_at timestamptz;
begin
  -- RLS continues to bind authenticated sender_id to auth.uid() and participation.
  -- Check the actual sender also in privileged INSERT contexts; no role exception.
  select p.data_processing_restricted_at into restricted_at
    from public.profiles p where p.id = new.sender_id for share;
  if restricted_at is not null then
    raise exception using errcode = '42501', message = 'account_data_processing_restricted';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.heartbeat_battle_spectator(p_match_id uuid, p_tab_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_sid uuid; v_uid uuid:=auth.uid(); v_status text; v_expiry timestamptz; v_result jsonb;
begin
  v_sid := battle_spectator_private.actor_session();
  perform pg_advisory_xact_lock(hashtextextended('battle:spectator:'||v_uid::text,0));
  select status into v_status from public.battle_matches where id=p_match_id for share;
  if not found or not battle_spectator_private.authorized(p_match_id,v_uid) then
    raise exception 'spectator_unavailable' using errcode='42501'; end if;
  select expires_at into v_expiry from battle_spectator_private.presence
    where match_id=p_match_id and user_id=v_uid and session_id=v_sid and tab_id=p_tab_id for update;
  if not found or v_expiry<=clock_timestamp() then
    raise exception 'spectator_presence_expired' using errcode='42501'; end if;
  if v_status in ('waiting','ready','live','dispute') then
    v_expiry := clock_timestamp()+interval '75 seconds';
    update battle_spectator_private.presence set expires_at=v_expiry
      where match_id=p_match_id and user_id=v_uid and session_id=v_sid and tab_id=p_tab_id;
  else
    delete from battle_spectator_private.presence
      where match_id=p_match_id and user_id=v_uid and session_id=v_sid and tab_id=p_tab_id;
    v_expiry := null;
  end if;
  v_result := battle_spectator_private.snapshot(p_match_id);
  return jsonb_build_object('match',v_result,'lease_expires_at',v_expiry,'heartbeat_seconds',20);
end $function$

CREATE OR REPLACE FUNCTION public.join_battle_as_moderator(p_match_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[m.host_id,m.guest_id] into d3_targets from public.battle_matches m where m.id=p_match_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.battle_matches m where m.id=p_match_id and array[m.host_id,m.guest_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;
  declare v_uid uuid:=auth.uid(); v_match public.battle_matches%rowtype; begin perform public.require_duelvanta_privileged_session(); if not public.has_staff_permission('battle_moderate',v_uid) then raise exception 'battle_moderate permission required'; end if; select * into v_match from public.battle_matches where id=p_match_id for update; if not found then raise exception 'Match not found'; end if; if v_match.status not in ('waiting','ready','live','dispute') then raise exception 'Match unavailable'; end if; if v_uid in (v_match.host_id,v_match.guest_id) then raise exception 'Players cannot moderate own match'; end if; if v_match.moderator_id is not null and v_match.moderator_id<>v_uid and not public.is_duelvanta_owner(v_uid) then raise exception 'Another moderator is assigned'; end if; update public.battle_matches set moderator_id=v_uid,moderator_joined_at=now(),moderation_state='joined',updated_at=now() where id=p_match_id; insert into public.admin_audit_log(actor_id,action,details) values(v_uid,'battle_moderator_joined',jsonb_build_object('match_id',p_match_id)); return p_match_id; end;
end
$function$

CREATE OR REPLACE FUNCTION public.join_battle_match(p_match_id uuid DEFAULT NULL::uuid, p_invite_code text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_match public.battle_matches; v_profile public.profiles;
begin
 if auth.uid() is null then raise exception 'not_authenticated'; end if;
 -- Keep the existing actor/Safety boundary; serialize admission with Hold writes.
 perform 1 from public.profiles where id=auth.uid() for share;
 if not exists(select 1 from public.profiles where id=auth.uid() and account_status in ('beta','active') and not coalesce(safety_restricted,false)) then raise exception 'battle_account_unavailable'; end if;
 if exists(select 1 from public.profiles where id=auth.uid() and data_processing_restricted_at is not null) then
   raise exception 'account_data_processing_restricted' using errcode='42501';
 end if;
 if p_match_id is not null then select * into v_match from public.battle_matches where id=p_match_id for update;
 else select * into v_match from public.battle_matches where invite_code=upper(trim(p_invite_code)) for update; end if;
 if v_match.id is null then raise exception 'Match nicht gefunden'; end if;
 if v_match.host_id=auth.uid() then return v_match.id; end if;
 if v_match.status<>'waiting' or v_match.guest_id is not null then raise exception 'Match ist nicht mehr verfügbar'; end if;
 if v_match.visibility='private' and (p_invite_code is null or upper(trim(p_invite_code))<>v_match.invite_code) then raise exception 'Ungültiger Einladungscode'; end if;
 if exists(select 1 from public.battle_matches where (host_id=auth.uid() or guest_id=auth.uid()) and status in ('waiting','ready','live')) then raise exception 'Du hast bereits ein aktives Match'; end if;
 select * into v_profile from public.profiles where id=auth.uid();
 update public.battle_matches set guest_id=auth.uid(),guest_display_name=coalesce(v_profile.display_name,v_profile.username,'DUELVANTA Player'),guest_founder_number=v_profile.founder_number,status='ready',updated_at=now() where id=v_match.id;
 return v_match.id;
end $function$

CREATE OR REPLACE FUNCTION public.join_battle_spectator(p_match_id uuid, p_tab_id uuid, p_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_sid uuid; v_uid uuid := auth.uid(); v_id uuid := p_match_id;
  v_match public.battle_matches%rowtype; v_link battle_spectator_private.links%rowtype;
  v_code text := nullif(upper(trim(p_code)),''); v_expiry timestamptz;
begin
  v_sid := battle_spectator_private.actor_session();
  if p_tab_id is null then raise exception 'spectator_invalid_tab'; end if;
  if v_code is not null and v_code !~ '^SP-[0-9A-F]{64}$' then
    raise exception 'spectator_unavailable' using errcode='42501'; end if;
  if v_id is null and v_code is not null then
    select l.match_id into v_id from battle_spectator_private.links l
      where l.enabled and l.secret_hash=encode(sha256(convert_to(v_code,'UTF8')),'hex');
  end if;
  -- Same-user tab limits and join/leave requests serialize; match lock prevents role races.
  perform pg_advisory_xact_lock(hashtextextended('battle:spectator:'||v_uid::text,0));
  select * into v_match from public.battle_matches where id=v_id for share;
  if not found or v_match.status not in ('waiting','ready','live','dispute') then
    raise exception 'spectator_unavailable' using errcode='42501'; end if;
  if v_uid=v_match.host_id or v_uid=v_match.guest_id or v_uid=v_match.moderator_id then
    raise exception 'spectator_role_conflict' using errcode='42501'; end if;
  if v_match.visibility='private' then
    select * into v_link from battle_spectator_private.links where match_id=v_id;
    if v_code is not null then
      if not coalesce(v_link.enabled,false) or v_link.secret_hash is distinct from encode(sha256(convert_to(v_code,'UTF8')),'hex') then
        raise exception 'spectator_unavailable' using errcode='42501'; end if;
      insert into battle_spectator_private.grants(match_id,user_id,generation)
        values(v_id,v_uid,v_link.generation) on conflict(match_id,user_id)
        do update set generation=excluded.generation;
    end if;
  elsif v_code is not null then
    raise exception 'spectator_unavailable' using errcode='42501';
  end if;
  if not battle_spectator_private.authorized(v_id,v_uid) then
    raise exception 'spectator_unavailable' using errcode='42501'; end if;
  delete from battle_spectator_private.presence where user_id=v_uid and expires_at<=clock_timestamp();
  if not exists(select 1 from battle_spectator_private.presence where match_id=v_id and user_id=v_uid and session_id=v_sid and tab_id=p_tab_id)
    and (select count(*) from battle_spectator_private.presence where user_id=v_uid)>=8 then
    raise exception 'spectator_tab_limit'; end if;
  v_expiry := clock_timestamp()+interval '75 seconds';
  insert into battle_spectator_private.presence(match_id,user_id,session_id,tab_id,expires_at)
    values(v_id,v_uid,v_sid,p_tab_id,v_expiry)
    on conflict(match_id,user_id,session_id,tab_id) do update set expires_at=excluded.expires_at;
  return jsonb_build_object('match',battle_spectator_private.snapshot(v_id),'lease_expires_at',v_expiry,'heartbeat_seconds',20);
end $function$

CREATE OR REPLACE FUNCTION public.leave_battle_match(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.battle_matches;
begin
  select * into v from public.battle_matches where id=p_match_id for update;
  if v.id is null then raise exception 'Match nicht gefunden'; end if;

  if auth.uid() not in (v.host_id, coalesce(v.guest_id, v.host_id)) then
    raise exception 'Nicht erlaubt';
  end if;

  if v.status in ('live','dispute') then
    raise exception 'Aktives oder strittiges Match kann nicht verlassen werden';
  end if;

  if v.status='completed' then
    return;
  end if;

  if auth.uid()=v.host_id then
    update public.battle_matches
      set status='cancelled', updated_at=now()
      where id=v.id;
  elsif auth.uid()=v.guest_id then
    update public.battle_matches
      set guest_id=null, guest_display_name=null, guest_founder_number=null,
          guest_ready=false, status='waiting', updated_at=now()
      where id=v.id;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.leave_battle_moderation(p_match_id uuid, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[m.host_id,m.guest_id] into d3_targets from public.battle_matches m where m.id=p_match_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
