CREATE OR REPLACE FUNCTION public.process_ranked_battle_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  h_before integer; g_before integer; h_after integer; g_after integer;
  h_games integer; g_games integer;
  expected_h double precision; actual_h double precision; k integer := 32; delta integer;
  result_text text;
begin
  if new.status<>'completed' or new.mode<>'ranked' or new.guest_id is null then return new; end if;
  if old.status='completed' then return new; end if;
  if exists(select 1 from public.battle_rating_events where match_id=new.id) then return new; end if;

  insert into public.battle_ratings(user_id,tcg) values(new.host_id,new.tcg) on conflict do nothing;
  insert into public.battle_ratings(user_id,tcg) values(new.guest_id,new.tcg) on conflict do nothing;

  if new.host_id::text < new.guest_id::text then
    perform 1 from public.battle_ratings where user_id=new.host_id and tcg=new.tcg for update;
    perform 1 from public.battle_ratings where user_id=new.guest_id and tcg=new.tcg for update;
  else
    perform 1 from public.battle_ratings where user_id=new.guest_id and tcg=new.tcg for update;
    perform 1 from public.battle_ratings where user_id=new.host_id and tcg=new.tcg for update;
  end if;

  select rating,games into h_before,h_games from public.battle_ratings where user_id=new.host_id and tcg=new.tcg;
  select rating,games into g_before,g_games from public.battle_ratings where user_id=new.guest_id and tcg=new.tcg;

  expected_h := 1.0 / (1.0 + power(10.0, (g_before-h_before)/400.0));
  if new.winner_id=new.host_id then actual_h:=1.0; result_text:='host';
  elsif new.winner_id=new.guest_id then actual_h:=0.0; result_text:='guest';
  else actual_h:=0.5; result_text:='draw'; end if;

  delta := round(k*(actual_h-expected_h));
  h_after := greatest(100,h_before+delta);
  g_after := greatest(100,g_before-delta);

  update public.battle_ratings set
    rating=h_after,
    games=games+1,
    wins=wins+case when result_text='host' then 1 else 0 end,
    losses=losses+case when result_text='guest' then 1 else 0 end,
    draws=draws+case when result_text='draw' then 1 else 0 end,
    updated_at=now()
  where user_id=new.host_id and tcg=new.tcg;

  update public.battle_ratings set
    rating=g_after,
    games=games+1,
    wins=wins+case when result_text='guest' then 1 else 0 end,
    losses=losses+case when result_text='host' then 1 else 0 end,
    draws=draws+case when result_text='draw' then 1 else 0 end,
    updated_at=now()
  where user_id=new.guest_id and tcg=new.tcg;

  insert into public.battle_rating_events(match_id,tcg,host_id,guest_id,host_before,host_after,guest_before,guest_after,host_delta,guest_delta,result)
  values(new.id,new.tcg,new.host_id,new.guest_id,h_before,h_after,g_before,g_after,h_after-h_before,g_after-g_before,result_text)
  on conflict (match_id) do nothing;

  return new;
end
$function$

