CREATE OR REPLACE FUNCTION public.resolve_battle_dispute(p_match_id uuid, p_result text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[m.host_id,m.guest_id] into d3_targets from public.battle_matches m where m.id=p_match_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.battle_matches m where m.id=p_match_id and array[m.host_id,m.guest_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;

declare
  v_uid uuid := auth.uid();
  v_match public.battle_matches%rowtype;
  v_winner uuid;
begin perform public.require_duelvanta_privileged_session();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.has_staff_permission('battle_moderate', v_uid) then
    raise exception 'battle_moderate permission required';
  end if;
  if p_result not in ('host','guest','draw') then
    raise exception 'Invalid dispute result';
  end if;

  select * into v_match from public.battle_matches where id=p_match_id for update;
  if not found then raise exception 'Match not found'; end if;
  if v_uid in (v_match.host_id, coalesce(v_match.guest_id,v_match.host_id)) then
    raise exception 'Players cannot resolve own match';
  end if;
  if v_match.status <> 'dispute' then
    raise exception 'Match is not in dispute';
  end if;
  if v_match.guest_id is null then raise exception 'Match has no opponent'; end if;

  v_winner := case when p_result='host' then v_match.host_id
                   when p_result='guest' then v_match.guest_id
                   else null end;

  update public.battle_matches
     set status='completed',
         winner_id=v_winner,
         completed_at=now(),
         moderation_state='resolved',
         moderator_id=coalesce(moderator_id,v_uid),
         moderator_joined_at=coalesce(moderator_joined_at,now()),
         moderation_note=left(nullif(trim(p_note),''),1000),
         paused_at=null,
         paused_by=null,
         updated_at=now()
   where id=p_match_id;

  insert into public.admin_audit_log(actor_id,action,details)
  values(v_uid,'battle_dispute_resolved',
         jsonb_build_object('match_id',p_match_id,'result',p_result,'note',left(p_note,1000)));

  return 'completed';
end;
end
$function$

